// Joins the follow-up migrations and the seed into one file, so updating the
// Supabase project is a single paste into the SQL editor: npm run db:bundle
// 001_schema.sql is left out on purpose: it is not re-runnable (run reset.sql first if you need it again).
import { readFileSync, writeFileSync } from "node:fs";

const files = [
  "supabase/migrations/002_work_functions.sql",
  "supabase/migrations/003_agent_functions.sql",
  "supabase/migrations/004_corner_cases.sql",
  "supabase/seed.sql",
];

const out = "supabase/paste_me.sql";
const body = files.map((f) => `-- >>>>>>>> ${f}\n${readFileSync(f, "utf8").trim()}\n`).join("\n");
writeFileSync(out, `-- Generated by "npm run db:bundle". Do not edit or commit; edit the source files instead.\n\n${body}`);
console.log(`Wrote ${out} (${files.length} files). Paste the whole file into the Supabase SQL editor and press Run.`);
